if(compile){stage="syntax-boundary-compile";sw.Restart();using(var provider=new CSharpCodeProvider()){var cp=new CompilerParameters(paths){GenerateExecutable=false,GenerateInMemory=false,IncludeDebugInformation=false,CompilerOptions="/optimize+ /nostdlib+",OutputAssembly=Path.Combine(Path.GetDirectoryName(output),"boundary-output.dll")};var compiled=provider.CompileAssemblyFromSource(cp,source);r["syntaxBoundaryCompile"]=new{ms=sw.Elapsed.TotalMilliseconds,success=!compiled.Errors.HasErrors,errors=compiled.Errors.Cast<CompilerError>().Where(x=>!x.IsWarning).Select(x=>x.ToString()).ToArray(),scope="existing CodeDom compiler component; not candidate C combined implementation"};}}r["success"]=true;
